uniform float speed : 0.0 .. 1.0 = 0.12;
uniform float wave_scale : 0.5 .. 4.0 = 1.8;
uniform float curtain_count : 1.0 .. 6.0 = 3.0;
uniform float intensity : 0.1 .. 1.0 = 0.7;
uniform vec3 color_a : color = 0.0, 0.8, 0.4;
uniform vec3 color_b : color = 0.2, 0.4, 1.0;
uniform vec3 color_c : color = 0.6, 0.1, 0.8;

state fixed ph_v;
state fixed ph_h1;
state fixed ph_h2;
state fixed ph_h3;
state fixed k_v;
state fixed k_h;
state fixed s_a;
state fixed s_b;
state fixed s_c;

void update() {
  ph_v = fract(ph_v + fixed(dt * speed * 0.5));
  ph_h1 = fract(ph_h1 + fixed(dt * speed * 0.17));
  ph_h2 = fract(ph_h2 + fixed(dt * speed * 0.23));
  ph_h3 = fract(ph_h3 + fixed(dt * speed * 0.31));
  k_v = fixed(wave_scale);
  k_h = fixed(curtain_count);
  s_a = fixed(intensity * 0.8);
  s_b = fixed(intensity * 1.0);
  s_c = fixed(intensity * 0.6);
}

vec3 shade(Led led) {
  fixed y = fixed(led.pos.y);
  fixed z = fixed(led.pos.z);
  fixed x = fixed(led.pos.x);

  fixed ang = atan2(z, x) + fixed(0.5);

  fixed v1 = sin(y * k_v + ph_v);
  fixed v2 = sin(y * k_v * fixed(1.5) + ph_v * fixed(1.3));
  fixed vertical = (v1 + v2 * fixed(0.5)) * fixed(0.66);

  fixed h1 = sin(ang * k_h + ph_h1);
  fixed h2 = sin(ang * k_h * fixed(1.5) + ph_h2);
  fixed h3 = sin(ang * k_h * fixed(0.7) + ph_h3);
  fixed horizontal = (h1 + h2 * fixed(0.5) + h3 * fixed(0.3)) * fixed(0.5);

  fixed pattern = vertical + horizontal;
  pattern = fract(pattern + fixed(0.5));

  fixed hue = pattern * fixed(0.33) + fixed(0.5);
  fixed sat = s_a + (s_b - s_a) * pattern;
  fixed val = s_c + (s_a - s_c) * pattern;

  return hsv2rgb(hue, sat, val);
}
